new file mode 100644
index 0000000..a2675c7
--- /dev/null
+++ b/store.test.mjs
@@ -0,0 +1,32 @@
+import assert from "node:assert/strict";
+import test from "node:test";
+
+import { createPlanningStore } from "./store.mjs";
+
+const TASK_ID = "task-1";
+const MALFORMED_REPORT = "{not json";
+
+test("rejecting a malformed report in a fresh store does not create canonical accepted state", () => {
+  const store = createPlanningStore();
+
+  const result = store.publish(TASK_ID, MALFORMED_REPORT);
+
+  assert.equal(result.status, "rejected");
+  assert.equal(store.canonicalRaw, null);
+  assert.deepEqual(store.rejectedPublications, [
+    { raw: MALFORMED_REPORT, reason: "invalid_json" },
+  ]);
+});
+
+test("rejecting a malformed report preserves existing canonical accepted state", () => {
+  const acceptedReport = JSON.stringify({ status: "ready", task_id: TASK_ID });
+  const store = createPlanningStore(acceptedReport);
+
+  const result = store.publish(TASK_ID, MALFORMED_REPORT);
+
+  assert.equal(result.status, "rejected");
+  assert.equal(store.canonicalRaw, acceptedReport);
+  assert.deepEqual(store.rejectedPublications, [
+    { raw: MALFORMED_REPORT, reason: "invalid_json" },
+  ]);
+});

